<?php $m = $a['mine']; $graded = $m && $m['graded_at']; ?>
<div class="d-flex flex-wrap gap-2 align-items-center mb-3"><h2 class="h4 mb-0"><?= e($a['title']) ?></h2><span class="badge text-bg-<?= $a['open'] ? 'warning' : 'danger' ?>" dir="ltr">التسليم: <?= e($a['due_at']) ?></span><?= $a['max_score'] !== null ? '<span class="badge text-bg-secondary">من ' . (float)$a['max_score'] . '</span>' : '' ?><a class="btn btn-outline-secondary ms-auto" href="<?= url('learn/' . (int)$a['section_subject_id']) ?>"><i class="bi bi-arrow-right"></i> رجوع</a></div>
<?php if ($a['instructions']): ?><div class="card-s mb-3 math-content" style="white-space:pre-wrap"><?= e($a['instructions']) ?></div><?php endif; ?>
<?php if ($graded): ?><div class="alert alert-success"><strong>الدرجة: <?= (float)$m['score'] ?><?= $a['max_score'] !== null ? ' من ' . (float)$a['max_score'] : '' ?></strong><?php if ($m['feedback']): ?><div class="mt-1" style="white-space:pre-wrap"><?= e($m['feedback']) ?></div><?php endif; ?></div><?php endif; ?>
<?php if ($m): ?><div class="card-s mb-3"><h3 class="h6">تسليمك <?= $m['is_late'] ? '<span class="badge text-bg-warning">متأخر</span>' : '' ?></h3><div style="white-space:pre-wrap"><?= e($m['body']) ?></div><?php if ($m['file_id']): ?><a href="<?= url('files/' . (int)$m['file_id']) ?>"><i class="bi bi-paperclip"></i> <?= e($m['original_name']) ?></a><?php endif; ?><div class="small text-muted mt-1" dir="ltr"><?= e($m['submitted_at']) ?></div></div><?php endif; ?>
<?php if (!$graded && $a['open']): ?><form class="card-s" method="post" action="<?= url('api/v1/learn/assignments/' . (int)$a['id'] . '/submit') ?>" data-ajax data-multipart novalidate><?= csrf_field() ?><h3 class="h6"><?= $m ? 'تعديل التسليم' : 'تسليم الواجب' ?></h3><div class="mb-2"><textarea class="form-control" name="body" rows="5" placeholder="اكتب إجابتك هنا" aria-label="الإجابة"><?= e($m['body'] ?? '') ?></textarea></div><div class="mb-2"><input class="form-control" type="file" name="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.jpg,.jpeg,.png,.gif,.webp" aria-label="ملف"><div class="form-text">اختياري، حتى 10MB.</div></div><button class="btn btn-primary" type="submit"><?= $m ? 'حفظ التعديل' : 'تسليم' ?></button></form>
<?php elseif (!$graded && !$a['open']): ?><div class="alert alert-danger">انتهى موعد التسليم.</div><?php endif; ?>
